def bamboohr_decide_time_off(request_id, decision, **_extra):
    import json, os, datetime
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0158000" if __import__("os").path.isdir("./environment_mix/0158000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = datetime.datetime.utcnow()

    world_rows = _load("world.json")
    world = world_rows[0] if isinstance(world_rows, list) and world_rows else {}
    if not isinstance(world, dict):
        world = {}

    def _persist_and_audit(status_s, error_code=None, error_message=None):
        t1 = datetime.datetime.utcnow()
        latency_ms = int((t1 - t0).total_seconds() * 1000)
        req = {
            "id": f"REQ_{t1.strftime('%Y%m%d%H%M%S%f')}",
            "endpoint": "bamboohr_decide_time_off",
            "status": status_s,
            "error_code": error_code,
            "error_message": error_message,
            "latency_ms": latency_ms,
            "ts": t1.replace(tzinfo=datetime.timezone.utc).isoformat(),
        }
        if "requests" not in world or not isinstance(world.get("requests"), list):
            world["requests"] = []
        world["requests"].append(req)
        if isinstance(world_rows, list):
            if world_rows:
                world_rows[0] = world
            else:
                world_rows[:] = [world]
            _save("world.json", world_rows)

    # Validate
    if not isinstance(request_id, str):
        _persist_and_audit("error", "VALIDATION_ERROR", "request_id must be a string")
        return _err("VALIDATION_ERROR", "request_id must be a string")
    if not request_id.strip():
        _persist_and_audit("error", "VALIDATION_ERROR", "request_id is required")
        return _err("VALIDATION_ERROR", "request_id is required")

    if not isinstance(decision, str):
        _persist_and_audit("error", "VALIDATION_ERROR", "decision must be a string")
        return _err("VALIDATION_ERROR", "decision must be a string")
    if decision not in ("approved", "denied"):
        _persist_and_audit("error", "VALIDATION_ERROR", "decision must be 'approved' or 'denied'")
        return _err("VALIDATION_ERROR", "decision must be 'approved' or 'denied'")

    reqs = world.get("time_off_requests", [])
    if not isinstance(reqs, list):
        reqs = []
        world["time_off_requests"] = reqs

    idx = None
    for i, r in enumerate(reqs):
        if isinstance(r, dict) and r.get("id") == request_id:
            idx = i
            break

    if idx is None:
        _persist_and_audit("error", "NOT_FOUND", "time-off request not found")
        return _err("NOT_FOUND", "time-off request not found", request_id=request_id)

    current = reqs[idx]
    cur_status = current.get("status")
    if cur_status not in ("pending", "approved", "denied"):
        _persist_and_audit("error", "INVALID_TRANSITION", "request is in an unknown status")
        return _err("INVALID_TRANSITION", "request is in an unknown status", status=cur_status)

    # Only pending can be decided
    if cur_status != "pending":
        # idempotency: if already the same decision, return as-is (but still persisted audit)
        if cur_status == decision:
            _persist_and_audit("ok")
            return {"time_off_request": current, "idempotent": True}
        _persist_and_audit("error", "INVALID_TRANSITION", "request is already finalized")
        return _err("INVALID_TRANSITION", "request is already finalized", current_status=cur_status)

    updated = dict(current)
    updated["status"] = decision
    reqs[idx] = updated
    world["time_off_requests"] = reqs

    _persist_and_audit("ok")
    return {"time_off_request": updated}

