        world["requests"].append(req)
        world["requests_count"] = int(world.get("requests_count") or 0) + 1
        world_rows[0] = world
        _save("world.json", world_rows)

    # Validate filters
    if from_contains is not None and not isinstance(from_contains, str):
        _audit("error", "VALIDATION_ERROR", "from_contains must be a string")
        return _err("VALIDATION_ERROR", "from_contains must be a string")
    if subject_contains is not None and not isinstance(subject_contains, str):
        _audit("error", "VALIDATION_ERROR", "subject_contains must be a string")
        return _err("VALIDATION_ERROR", "subject_contains must be a string")
    if label is not None and not isinstance(label, str):
        _audit("error", "VALIDATION_ERROR", "label must be a string")
        return _err("VALIDATION_ERROR", "label must be a string")

    # Messages live in world.messages (shared store for this bench)
    messages = world.get("messages")
    if not isinstance(messages, list):
        messages = []

    # Recognized labels are those already present in messages' label_ids for this mailbox.
    if label is not None:
        known_labels = set()
        for m in messages:
            if isinstance(m, dict) and isinstance(m.get("label_ids"), list):
                for lid in m.get("label_ids"):
                    if isinstance(lid, str):
                        known_labels.add(lid)
        if known_labels and label not in known_labels:
            _audit("error", "VALIDATION_ERROR", "label is not recognized for this mailbox", label=label)
            return _err("VALIDATION_ERROR", "label is not recognized for this mailbox", label=label)
        # If no labels exist in store, accept any label but will match nothing (normal read behavior).

    def _contains(hay, needle):
        if needle is None:
            return True
        if not isinstance(hay, str):
            return False
        return needle.lower() in hay.lower()

    out = []
    for m in messages:
        if not isinstance(m, dict):
            continue

        if from_contains is not None and not _contains(m.get("from_"), from_contains):
            continue
        if subject_contains is not None and not _contains(m.get("subject"), subject_contains):
            continue
        if label is not None:
            lids = m.get("label_ids")
            if not isinstance(lids, list) or label not in lids:
                continue

        out.append(m)

    # Sort newest-first by internal_date/date if available (typical Gmail UX)
    def _ts_key(msg):
        v = msg.get("internal_date")
        if isinstance(v, int):
            return v
        v = msg.get("date")
        if isinstance(v, int):
            return v
        return 0

    out.sort(key=_ts_key, reverse=True)

    _audit("ok", matched=len(out))
    return {
        "messages": out,
        "total": len(out),
        "has_more": False,
        "next_cursor": None
    }

