        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    world = _load("world.json")

    if not isinstance(id, str) or not id.strip():
        return _err("VALIDATION_ERROR", "id is required and must be a non-empty string", id=id)

    # world.json may be empty list (0 rows) or a single object; normalize.
    if isinstance(world, list):
        if not world:
            return _err("UNAUTHORIZED", "no connected mailbox available")
        # pick a world row that actually has messages
        w = None
        for row in world:
            if isinstance(row, dict) and isinstance(row.get("messages"), list):
                w = row
                break
        if w is None:
            return _err("UNAUTHORIZED", "no connected mailbox available")
    elif isinstance(world, dict):
        w = world
    else:
        return _err("UNAUTHORIZED", "no connected mailbox available")

    messages = w.get("messages")
    if not isinstance(messages, list):
        return _err("UNAUTHORIZED", "no connected mailbox available")

    found = None
    for m in messages:
        if isinstance(m, dict) and m.get("id") == id:
            found = m
            break

    if found is None:
        return _err("NOT_FOUND", "message not found", id=id)

    # Optional: record usage if a request/audit log exists in the store (it doesn't in this schema).
