        }
        if "requests" not in world or not isinstance(world.get("requests"), list):
            world["requests"] = []
        world["requests"].append(req)
        if isinstance(world_rows, list):
            if world_rows:
                world_rows[0] = world
            else:
                world_rows[:] = [world]
            _save("world.json", world_rows)

    # Validation helpers
    import re
    email_re = re.compile(r"^[^@\s]+@[^@\s]+\.[^@\s]+$")

    if not isinstance(to, list):
        _persist_and_audit("error", "VALIDATION_ERROR", "to must be an array of email strings")
        return _err("VALIDATION_ERROR", "to must be an array of email strings")
    if len(to) == 0:
        _persist_and_audit("error", "VALIDATION_ERROR", "to cannot be empty")
        return _err("VALIDATION_ERROR", "to cannot be empty")

    if cc is None:
        cc = []
    if not isinstance(cc, list):
        _persist_and_audit("error", "VALIDATION_ERROR", "cc must be an array of email strings")
        return _err("VALIDATION_ERROR", "cc must be an array of email strings")

    def _clean_list(lst, field):
        out = []
        for v in lst:
            if not isinstance(v, str):
                raise ValueError(f"{field} entries must be strings")
            s = v.strip()
            if not s:
                raise ValueError(f"{field} entries cannot be blank")
            if not email_re.match(s):
                raise ValueError(f"invalid email address in {field}: {s}")
            out.append(s)
        return out

    try:
        to_clean = _clean_list(to, "to")
        cc_clean = _clean_list(cc, "cc")
    except ValueError as e:
        _persist_and_audit("error", "VALIDATION_ERROR", str(e))
        return _err("VALIDATION_ERROR", str(e))

    if not isinstance(subject, str):
        _persist_and_audit("error", "VALIDATION_ERROR", "subject must be a string")
        return _err("VALIDATION_ERROR", "subject must be a string")
