        _persist_and_audit("error", "VALIDATION_ERROR", "body must be a string")
        return _err("VALIDATION_ERROR", "body must be a string")
    if not body.strip():
        _persist_and_audit("error", "VALIDATION_ERROR", "body is required")
        return _err("VALIDATION_ERROR", "body is required")

    # Ensure messages array exists
    if "messages" not in world or not isinstance(world.get("messages"), list):
        world["messages"] = []
    messages = world["messages"]

    # Determine sender
    from_addr = world.get("account")
    if not isinstance(from_addr, str) or not from_addr.strip():
        # fallback sender - still deterministic & valid
        from_addr = "user@example.com"

    now = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)
    epoch_ms = int(now.timestamp() * 1000)
    ts = f"{now.timestamp():.6f}"

    # Generate unique-ish id
    msg_id = f"MSG_{now.strftime('%Y%m%d%H%M%S%f')}"

    msg = {
        "id": msg_id,
        "from_": from_addr,
        "to": to_clean,
        "cc": cc_clean,
        "bcc": [],
        "subject": subject,
        "body_plain": body,
        "body_html": None,
        "label_ids": ["SENT"],
        "is_read": True,
        "is_starred": False,
        "date": epoch_ms,
        "internal_date": epoch_ms,
        "ts": ts,
        "channel_id": "C_GEN",   # schema requires enum; email doesn't have channel but datastore does
        "user_id": "U_BOT",      # schema requires enum
        "text": body,
        "thread_ts": None,
        "reply_count": 0,
        "is_bot": True,
        "reactions": []
    }

    messages.append(msg)
    world["messages"] = messages

    _persist_and_audit("ok")
    return {"message": msg}

