            _save("world.json", world_rows)

    # Defaults
    if limit is None:
        limit = 100

    # Validate
    if not isinstance(limit, int):
        _audit("error", "VALIDATION_ERROR", "limit must be an integer")
        return _err("VALIDATION_ERROR", "limit must be an integer")
    if limit < 1 or limit > 200:
        _audit("error", "VALIDATION_ERROR", "limit must be between 1 and 200")
        return _err("VALIDATION_ERROR", "limit must be between 1 and 200")

    if cursor is not None and not isinstance(cursor, str):
        _audit("error", "VALIDATION_ERROR", "cursor must be a string")
        return _err("VALIDATION_ERROR", "cursor must be a string")

    channels = world.get("channels", [])
    if not isinstance(channels, list):
        channels = []

    # Cursor scheme: "offset:<int>"
    offset = 0
    if cursor:
        if not cursor.startswith("offset:"):
            _audit("error", "VALIDATION_ERROR", "invalid cursor")
            return _err("VALIDATION_ERROR", "invalid cursor")
        try:
            offset = int(cursor.split(":", 1)[1])
        except ValueError:
            _audit("error", "VALIDATION_ERROR", "invalid cursor")
            return _err("VALIDATION_ERROR", "invalid cursor")
        if offset < 0:
            _audit("error", "VALIDATION_ERROR", "invalid cursor")
            return _err("VALIDATION_ERROR", "invalid cursor")

    total = len([c for c in channels if isinstance(c, dict)])
    page = [c for c in channels if isinstance(c, dict)][offset:offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = f"offset:{next_offset}" if has_more else None

    _audit("ok")
    return {
        "channels": page,
        "pagination": {"total": total, "has_more": has_more, "next_cursor": next_cursor}
    }

def slack_find_channel(name, **_extra):
    import json, os, datetime, time, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0158000" if __import__("os").path.isdir("./environment_mix/0158000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    world = _load("world.json")

    if not isinstance(name, str) or not name.strip():
        return _err("VALIDATION_ERROR", "name is required and must be a non-empty string", name=name)

    # Slack channel names: allow letters, digits, hyphen, underscore; 1-80 typical.
    n = name.strip().lstrip("#")
    if not re.fullmatch(r"[a-z0-9][a-z0-9_-]{0,79}", n.lower()):
        return _err("VALIDATION_ERROR", "name is not a valid Slack channel name", name=name)

    # Normalize datastore
    if isinstance(world, list):
        if not world:
            return _err("UNAUTHORIZED", "no Slack connection available")
        w = None
        for row in world:
            if isinstance(row, dict) and isinstance(row.get("channels"), list):
                w = row
                break
        if w is None:
            return _err("UNAUTHORIZED", "no Slack connection available")
    elif isinstance(world, dict):
        w = world
    else:
        return _err("UNAUTHORIZED", "no Slack connection available")

    channels = w.get("channels")
    if not isinstance(channels, list):
        return _err("UNAUTHORIZED", "no Slack connection available")

    target = n.lower()
    for c in channels:
        if not isinstance(c, dict):
            continue
        cname = c.get("name")
        if isinstance(cname, str) and cname.strip().lstrip("#").lower() == target:
            return {"channel": c}

    return _err("NOT_FOUND", "no visible channel matches the provided name", name=name)

def slack_get_channel_messages(channel_id, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0158000" if __import__("os").path.isdir("./environment_mix/0158000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    world = _load("world.json")

    if not isinstance(channel_id, str) or not channel_id.strip():
        return _err("VALIDATION_ERROR", "channel_id is required and must be a non-empty string", channel_id=channel_id)

    cid = channel_id.strip()

    # Normalize datastore
    if isinstance(world, list):
        if not world:
            return _err("UNAUTHORIZED", "no Slack connection available")
        w = None
        for row in world:
            if isinstance(row, dict) and isinstance(row.get("channels"), list) and isinstance(row.get("messages"), list):
                w = row
                break
        if w is None:
            # fall back to any row with channels at least
            for row in world:
                if isinstance(row, dict) and isinstance(row.get("channels"), list):
                    w = row
                    break
        if w is None:
            return _err("UNAUTHORIZED", "no Slack connection available")
    elif isinstance(world, dict):
        w = world
    else:
        return _err("UNAUTHORIZED", "no Slack connection available")

    channels = w.get("channels")
    if not isinstance(channels, list):
        return _err("UNAUTHORIZED", "no Slack connection available")

    channel = None
    for c in channels:
        if isinstance(c, dict) and c.get("id") == cid:
            channel = c
            break
    if channel is None:
        return _err("NOT_FOUND", "channel not found", channel_id=cid)

    # Permission rule: private channels require membership. No membership model exists in this schema,
    # so treat visibility in channel directory as "accessible". If present and private, still allow read.
    msgs = w.get("messages")
    if not isinstance(msgs, list):
        msgs = []

    out = []
    for m in msgs:
        if isinstance(m, dict) and m.get("channel_id") == cid:
            out.append(m)

    # Reads that match nothing should return empty set (not error).
    return {"messages": out, "channel": channel, "total": len(out)}

def slack_send_channel_message(channel_id, text, **_extra):
    import json, os, datetime
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0158000" if __import__("os").path.isdir("./environment_mix/0158000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = datetime.datetime.utcnow()

    world_rows = _load("world.json")
    world = world_rows[0] if isinstance(world_rows, list) and world_rows else {}
    if not isinstance(world, dict):
        world = {}

    def _persist_and_audit(status_s, error_code=None, error_message=None):
        t1 = datetime.datetime.utcnow()
        latency_ms = int((t1 - t0).total_seconds() * 1000)
        req = {
            "id": f"REQ_{t1.strftime('%Y%m%d%H%M%S%f')}",
            "endpoint": "slack_send_channel_message",
            "status": status_s,
            "error_code": error_code,
            "error_message": error_message,
            "latency_ms": latency_ms,
            "ts": t1.replace(tzinfo=datetime.timezone.utc).isoformat(),
        }
        if "requests" not in world or not isinstance(world.get("requests"), list):
            world["requests"] = []
        world["requests"].append(req)
        if isinstance(world_rows, list):
            if world_rows:
                world_rows[0] = world
            else:
                world_rows[:] = [world]
            _save("world.json", world_rows)

    # Validate
    if not isinstance(channel_id, str):
        _persist_and_audit("error", "VALIDATION_ERROR", "channel_id must be a string")
        return _err("VALIDATION_ERROR", "channel_id must be a string")
    if not channel_id.strip():
        _persist_and_audit("error", "VALIDATION_ERROR", "channel_id is required")
        return _err("VALIDATION_ERROR", "channel_id is required")

    if not isinstance(text, str):
        _persist_and_audit("error", "VALIDATION_ERROR", "text must be a string")
        return _err("VALIDATION_ERROR", "text must be a string")
    if not text.strip():
        _persist_and_audit("error", "VALIDATION_ERROR", "text is required")
        return _err("VALIDATION_ERROR", "text is required")

    channels = world.get("channels", [])
    if not isinstance(channels, list):
        channels = []

    chan = next((c for c in channels if isinstance(c, dict) and c.get("id") == channel_id), None)
    if chan is None:
        _persist_and_audit("error", "NOT_FOUND", "channel not found")
        return _err("NOT_FOUND", "channel not found", channel_id=channel_id)

    # Ensure messages array exists
    if "messages" not in world or not isinstance(world.get("messages"), list):
        world["messages"] = []
    messages = world["messages"]

    now = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)
    ts = f"{now.timestamp():.6f}"
    epoch_ms = int(now.timestamp() * 1000)

    bot_user_id = world.get("bot_user_id")
    if bot_user_id not in ("U_BOT", "U_HR1", "U_HR2", "U_REC"):
        bot_user_id = "U_BOT"

    msg = {
        "id": None,
        "from_": world.get("account") if isinstance(world.get("account"), str) else "",
        "to": [],
        "cc": [],
        "bcc": [],
        "subject": "",
        "body_plain": "",
        "body_html": None,
        "label_ids": [],
        "is_read": True,
        "is_starred": False,
        "date": epoch_ms,
        "internal_date": epoch_ms,
        "ts": ts,
        "channel_id": channel_id,
        "user_id": bot_user_id,
        "text": text,
        "thread_ts": None,
        "reply_count": 0,
        "is_bot": True,
        "reactions": []
    }

    messages.append(msg)
    world["messages"] = messages

    _persist_and_audit("ok")
    return {"message": msg, "channel": chan}
